// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }
    function testFuzz_property(uint256 t1, uint256 t2, uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        t1 = bound(t1, block.timestamp + 1, block.timestamp + 1e18);
        t2 = bound(t2, t1 + 1, block.timestamp + 2e18);
        amount = bound(amount, 0, 100 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t1);
        vm.prank(actor);
        c.Put{value: 0}(t2);
        (uint unlockTime, ) = c.Acc(actor);
        assertTrue(unlockTime == t2);
    }
}
